tools.example:
mphstart(2036);
model = mphload('busbar.mph');
model.param.set('Vtot', '25[mV]');
model.study('std1').run;
mphsave(model, 'busbar_25mV.mph');
mphlaunch(model);   % opens the Desktop to look at the result

try
    model.study('std1').run;
catch ME
    disp(ME.message);
    mphshowerrors(model);
end

model = mphload('bracket.mph');
figure
mphgeom(model, 'geom1', 'facelabels', 'on', 'facealpha', 0.4);
title('Boundary numbers');

model.mesh('mesh1').run;
s = mphmeshstats(model, 'mesh1');
fprintf('%d elements, min quality %.3f\n', sum(s.numelem), s.minquality);
[~, d] = mphmeshstats(model, 'mesh1');
nodes = d.vertex';           % N x 3 coordinates
tets  = d.elem{strcmp(d.types, 'tet')}' + 1;   % 1-based connectivity

model.result.create('pg1', 'PlotGroup3D');
model.result('pg1').create('surf1', 'Surface');
model.result('pg1').feature('surf1').set('expr', 'T');
figure
mphplot(model, 'pg1', 'rangenum', 1);
colormap(jet)
print('-dpng', 'temperature.png');

for V = 10:10:40
    model.param.set('Vtot', sprintf('%d[mV]', V));
    model.study('std1').run;
    fprintf('V=%d mV: Tmax = %.2f K\n', V, mphmax(model, 'T', 'volume'));
end

model.study('std1').run;     % frequency sweep with two ports
S = mphevalglobalmatrix(model, 'emw.S');   % 2 x 2 x Nfreq
f = mphglobal(model, 'freq');
plot(f, 20*log10(abs(squeeze(S(1,1,:)))));

t = mphtable(model, 'tbl1');
disp(t.headers);
data = t.data;         % columns as in the Table window
info = mphsolinfo(model, 'soltag', 'sol1');
disp(info.paramvals);

hf = model.component('comp1').physics('ht').feature('hf1');
s = mphgetproperties(hf);
disp(s)                       % all property values
hf.set('h', 20);
exprs = mphgetexpressions(model.param);
disp(exprs)                   % {name, expression, description}

% find the outlet face at x = L regardless of numbering
L = model.param.evaluate('L');
out = mphselectcoords(model, 'geom1', [L; 0.01; 0.01], 'boundary', 'radius', 1e-4);
model.component('comp1').physics('spf').feature('out1').selection.set(out);

model.sol('sol1').feature('st1').run; model.sol('sol1').feature('v1').run;
M = mphmatrix(model, 'sol1', 'out', {'Kc', 'Lc', 'Null', 'ud', 'uscale'});
uc = M.Kc \ M.Lc;
u = M.Null*uc + M.ud;      % restore constrained DOFs
u = u .* M.uscale;         % undo scaling
info = mphxmeshinfo(model);  % map DOFs to nodes

S = mphstate(model, 'sol1', 'out', {'A','B','C','D'}, 'input', {'Q_in'}, 'output', {'T_sensor'});
sys = ss(full(S.A), full(S.B), full(S.C), full(S.D));
step(sys, 100);

U = mphgetu(model);
info = mphxmeshinfo(model);
iT = strcmp(info.dofs.dofnames(info.dofs.nameinds + 1), 'comp1.T');
Tnodes = U(iT);
xyz = info.dofs.coords(:, iT)';

m = mphmeasure(model, 'geom1', 'domain', 'selection', [1 2]);
fprintf('Total volume: %.4e m^3\n', m.volume);
walls = mphgetadj(model, 'geom1', 'boundary', 'domain', 1);
model.component('comp1').physics('spf').feature('wall1').selection.set(walls);

[X, Y] = meshgrid(0:0.01:1, 0:0.01:0.5);
T = 300 + 50*X.*Y;
mphinterpolationfile([X(:) Y(:) T(:)], 'x y T', 'Tfield.txt');
model.func.create('int1', 'Interpolation');
model.func('int1').set('source', 'file');
model.func('int1').set('filename', 'Tfield.txt');
model.func('int1').set('nargs', 2);
model.func('int1').importData;

pd = mphparticle(model, 'dataset', 'part1', 'expr', {'qx','qy'});
plot(squeeze(pd.d1(:,:,end)), squeeze(pd.d2(:,:,end)), '.');
mphimage(model, 'pg1', 'result.png', 'width', 1600, 'height', 1000);

% MATLAB before running the Simulink model
mphstart(2036);
% In Simulink: COMSOL Cosimulation block -> Model: heater.mph, Study: std1
% Inputs: P_heater ; Outputs: T_sensor ; connect a PID controller between them
sim('thermal_control');

model.material().create("mat1", "Common");
model.material("mat1").label("Aluminum");
model.material("mat1").propertyGroup("def").set("thermalconductivity", new String[]{"238"});
model.component("comp1").material().create("matlnk1", "Link");
model.component("comp1").material("matlnk1").set("link", "mat1");
model.component("comp1").material("matlnk1").selection().set(new int[]{1, 2});

model.material().create("lmat1", "LayeredMaterial");
model.material("lmat1").set("layername", new String[]{"0 deg", "90 deg", "0 deg"});
model.material("lmat1").set("link", new String[]{"mat1", "mat1", "mat1"});
model.material("lmat1").set("rotation", new String[]{"0", "90", "0"});
model.material("lmat1").set("thickness", new String[]{"0.25[mm]", "0.25[mm]", "0.25[mm]"});
model.component("comp1").material().create("llmat1", "LayeredMaterialLink");
model.component("comp1").material("llmat1").set("link", "lmat1");
model.component("comp1").material("llmat1").selection().set(new int[]{1});

model.material().create("extmat1", "External");
model.material("extmat1").set("interfacetype", "generalStressStrain");
model.material("extmat1").set("path", "C:/lib/hyperfoam.dll");
model.component("comp1").physics("solid").create("emm1", "ExternalStressStrainRelation", 3);
model.component("comp1").physics("solid").feature("emm1").set("externalMaterial", "extmat1");

model.component("comp1").material("mat1").propertyGroup("def").func().create("kT", "Interpolation");
model.component("comp1").material("mat1").propertyGroup("def").func("kT").set("table", new String[][]{{"293", "400"}, {"373", "390"}, {"473", "380"}});
model.component("comp1").material("mat1").propertyGroup("def").func("kT").set("interp", "linear");
model.component("comp1").material("mat1").propertyGroup("def").set("thermalconductivity", new String[]{"kT(T[1/K])[W/(m*K)]"});
model.component("comp1").material("mat1").propertyGroup("def").addInput("temperature");

model.component("comp1").mesh("mesh1").create("imp1", "Import");
model.component("comp1").mesh("mesh1").feature("imp1").set("source", "nastran");
model.component("comp1").mesh("mesh1").feature("imp1").set("filename", "C:/mesh/bracket.bdf");
model.component("comp1").mesh("mesh1").feature("imp1").set("bndparttype", "auto");
model.component("comp1").mesh("mesh1").run();

model.component("comp1").geom("geom1").create("imp1", "Import");
model.component("comp1").geom("geom1").feature("imp1").set("type", "mesh");
model.component("comp1").geom("geom1").feature("imp1").set("filename", "C:/scan/femur.stl");
model.component("comp1").geom("geom1").feature("imp1").set("stlfacepartition", "auto");
model.component("comp1").geom("geom1").run();

model.result().export().create("data1", "Data");
model.result().export("data1").set("expr", new String[]{"T", "spf.U"});
model.result().export("data1").set("filename", "C:/out/result.vtu");
model.result().export("data1").set("struct", "vtk");
model.result().export("data1").run();

model.result().export().create("tou1", "Touchstone");
model.result().export("tou1").set("filename", "C:/out/patch_antenna.s1p");
model.result().export("tou1").set("dataformat", "db");
model.result().export("tou1").run();

model.result().export().create("anim1", "Animation");
model.result().export("anim1").set("plotgroup", "pg1");
model.result().export("anim1").set("type", "movie");
model.result().export("anim1").set("movietype", "gif");
model.result().export("anim1").set("giffilename", "C:/out/transient.gif");
model.result().export("anim1").set("framesel", "all");
model.result().export("anim1").set("fps", 10);
model.result().export("anim1").run();

model.component("comp1").geom("geom1").create("imp1", "Import");
model.component("comp1").geom("geom1").feature("imp1").set("filename", "C:/cad/housing.x_t");
model.component("comp1").geom("geom1").feature("imp1").importData();
model.component("comp1").geom("geom1").run();
model.component("comp1").geom("geom1").export().set("filename", "C:/cad/housing_simplified.step");
